command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="74550ff2c67633371d1c3ad2e266c32a7e7c8ed1";$candidate="cf9aee51575922869ad47a0cd2b0dde1a5c3faef";$branch="work/unc-network-metadata-sort-20261007"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "network metadata FAST successor fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before network metadata FAST successor"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "network metadata FAST successor candidate moved"}
$temp=Join-Path $env:RUNNER_TEMP ("fly-network-metadata-fast-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
 & git worktree add --detach $temp $candidate
 if($LASTEXITCODE -ne 0){throw "network metadata FAST worktree add failed"}
 Set-Location -LiteralPath $temp
 & git diff --check ($main+"..."+$candidate)
 if($LASTEXITCODE -ne 0){throw "network metadata FAST diff check failed"}
 & python -X utf8 tools\winui\run_checks.py fast --before $main --head $candidate
 if($LASTEXITCODE -ne 0){throw "network metadata FAST successor failed"}
 Write-Host "NETWORK_METADATA_FAST_SUCCESSOR=PASS"
 Write-Host "NETWORK_METADATA_DIFF_CHECK=PASS"
}finally{
 Set-Location -LiteralPath $repo
 if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
 & git worktree prune
}
